using System.Security.Claims;using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Domain.Inventory;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;[ApiController,Route("api/v1/inventories")]public sealed class InventoriesController(DadoRetailDbContext db):ControllerBase{
[HttpGet,HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.Inventories.AsNoTracking().Include(x=>x.Lines).OrderByDescending(x=>x.CreatedAtUtc).Take(200).Select(x=>new{x.Id,x.Number,x.WarehouseId,x.Status,x.ApprovedAtUtc,Lines=x.Lines.Count,Difference=x.Lines.Sum(l=>l.ActualQuantity-l.BookQuantity)}).ToListAsync(ct));
[HttpGet("{id:guid}"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Get(Guid id,CancellationToken ct){var d=await db.Inventories.AsNoTracking().Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();var productIds=d.Lines.Select(x=>x.ProductId).ToArray();var products=await db.Products.AsNoTracking().Where(x=>productIds.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct);return Ok(new{d.Id,d.Number,d.WarehouseId,d.Status,d.ApprovedAtUtc,d.ApprovedByUserId,lines=d.Lines.OrderBy(x=>products.TryGetValue(x.ProductId,out var p)?p.Name:string.Empty).Select(x=>new{x.Id,x.ProductId,Sku=products.TryGetValue(x.ProductId,out var p)?p.Sku:null,Name=products.TryGetValue(x.ProductId,out p)?p.Name:null,x.BookQuantity,x.ActualQuantity,x.Difference})});}
[HttpPost,HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Create(CreateInventoryRequest r,CancellationToken ct){if(!await db.Warehouses.AnyAsync(x=>x.Id==r.WarehouseId,ct))return BadRequest(new{message="Склад не найден"});if(string.IsNullOrWhiteSpace(r.Number))return BadRequest(new{message="Укажите номер инвентаризации"});if(await db.Inventories.AnyAsync(x=>x.WarehouseId==r.WarehouseId&&x.Number==r.Number.Trim(),ct))return Conflict(new{message="Инвентаризация с таким номером уже существует"});var d=new InventoryDocument(r.WarehouseId,r.Number);db.Add(d);await db.SaveChangesAsync(ct);return Ok(new{d.Id,d.Status});}
[HttpPost("{id:guid}/start"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Start(Guid id,CancellationToken ct){var d=await db.Inventories.Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();if(d.Status!=InventoryStatus.Draft)return Conflict(new{message="Инвентаризация уже начата или закрыта"});var balances=await db.StockBalances.AsNoTracking().Where(x=>x.WarehouseId==d.WarehouseId).ToListAsync(ct);foreach(var b in balances)d.Count(b.ProductId,b.Quantity,0);d.Start();foreach(var b in balances)d.Count(b.ProductId,b.Quantity,0);await db.SaveChangesAsync(ct);return Ok(new{d.Id,d.Status,Lines=d.Lines.Count});}
[HttpPost("{id:guid}/count"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Count(Guid id,CountRequest r,CancellationToken ct){var d=await db.Inventories.Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();if(d.Status!=InventoryStatus.Counting)return Conflict(new{message="Инвентаризация не находится в режиме подсчета"});if(r.ActualQuantity<0)return BadRequest(new{message="Количество не может быть отрицательным"});var productId=await db.Barcodes.Where(x=>x.Value==r.Barcode).Select(x=>(Guid?)x.ProductId).FirstOrDefaultAsync(ct);if(productId is null)return NotFound(new{message="Товар не найден"});var existing=d.Lines.FirstOrDefault(x=>x.ProductId==productId.Value);var book=existing?.BookQuantity??await db.StockBalances.Where(x=>x.WarehouseId==d.WarehouseId&&x.ProductId==productId).Select(x=>x.Quantity).FirstOrDefaultAsync(ct);d.Count(productId.Value,book,r.ActualQuantity);await db.SaveChangesAsync(ct);return Ok(new{productId,book,r.ActualQuantity,difference=r.ActualQuantity-book});}
[HttpPost("{id:guid}/submit"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Submit(Guid id,CancellationToken ct){var d=await db.Inventories.Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();if(d.Status!=InventoryStatus.Counting||d.Lines.Count==0)return Conflict(new{message="Нет данных для передачи на утверждение"});d.Submit();await db.SaveChangesAsync(ct);return Ok(new{d.Id,d.Status});}
[HttpPost("{id:guid}/cancel"),HasPermission(Permissions.InventoryCreate)]public async Task<IActionResult>Cancel(Guid id,CancellationToken ct){var d=await db.Inventories.FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();if(d.Status==InventoryStatus.Approved)return Conflict(new{message="Утвержденную инвентаризацию отменить нельзя"});d.Cancel();await db.SaveChangesAsync(ct);return Ok(new{d.Id,d.Status});}
[HttpPost("{id:guid}/approve"),HasPermission(Permissions.InventoryApprove)]public async Task<IActionResult>Approve(Guid id,CancellationToken ct){if(!Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("sub"),out var userId))return Unauthorized();await using var tx=await db.Database.BeginTransactionAsync(ct);var d=await db.Inventories.Include(x=>x.Lines).FirstOrDefaultAsync(x=>x.Id==id,ct);if(d is null)return NotFound();if(d.Status!=InventoryStatus.AwaitingApproval)return Conflict(new{message="Документ не ожидает утверждения"});foreach(var l in d.Lines){var b=await db.StockBalances.FirstOrDefaultAsync(x=>x.WarehouseId==d.WarehouseId&&x.ProductId==l.ProductId,ct);if(b is null){b=new StockBalance(d.WarehouseId,l.ProductId);db.StockBalances.Add(b);}var delta=l.ActualQuantity-b.Quantity;if(delta!=0){b.Apply(delta);db.StockMovements.Add(new StockMovement(d.WarehouseId,l.ProductId,delta,StockMovementType.Adjustment,d.Id));}}d.Approve(userId);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new{d.Id,d.Status,d.ApprovedAtUtc});}}
public sealed record CreateInventoryRequest(Guid WarehouseId,string Number);public sealed record CountRequest(string Barcode,decimal ActualQuantity);
